﻿# --- BOOTSTRAP: ALWAYS IMPORT MODULE CORRECTLY ---

# Folder containing THIS test file
$TestRoot = Split-Path -Parent $MyInvocation.MyCommand.Path

# The module file is in the SAME folder as the test file
$ModulePath = Join-Path $TestRoot '..\..\Projects\Tooling\modules\ConfigMerge\ConfigMerge.psm1'

# Import the module
Import-Module $ModulePath -Force

# Verify import
if (-not (Get-Command Merge-Config -ErrorAction SilentlyContinue)) {
    throw "Merge-Config is NOT imported. ModulePath = $ModulePath"
}

Describe 'ConfigMerge Merge-Config' {

    Context 'Merge order and scalar overwrite' {
        It 'applies precedence Defaults → Config → Mode → Style → CLI' {
            $defaults = @{ option = 'defaults' }
            $mode     = @{ option = 'mode' }
            $config   = @{ option = 'config' }
            $style    = @{ option = 'style' }
            $cli      = @{ option = 'cli' }

            $result = Merge-Config -Defaults $defaults -Mode $mode -Config $config -Style $style -Cli $cli
            $result.option | Should -Be 'cli'
        }

        It 'does not erase values when incoming is null' {
            $defaults = @{ option = 'defaults' }
            $mode     = @{ option = $null }

            $result = Merge-Config -Defaults $defaults -Mode $mode
            $result.option | Should -Be 'defaults'
        }
    }

    Context 'Array joins' {
        It 'joins arrays via union' {
            $defaults = @{ includeTypes = @('a','b') }
            $mode     = @{ includeTypes = @('b','c') }

            $result = Merge-Config -Defaults $defaults -Mode $mode
            $result.includeTypes | Should -Be @('a','b','c')
        }
    }

    Context 'ConflictMode precedence' {
        It 'uses CLI conflictMode over others' {
            $defaults = @{ conflictMode = 'removeWins' }
            $mode     = @{ conflictMode = 'includeWins' }
            $config   = @{ conflictMode = 'unionWins' }
            $style    = @{ conflictMode = 'removeWins' }
            $cli      = @{ conflictMode = 'includeWins' }

            $result = Merge-Config -Defaults $defaults -Mode $mode -Config $config -Style $style -Cli $cli
            $result.conflictMode | Should -Be 'includeWins'
        }

        It 'defaults to removeWins when missing' {
            $result = Merge-Config -Defaults @{}
            $result.conflictMode | Should -Be 'unionWins'
        }
    }

    Context 'removeWins behavior' {
        It 'excludeTypes removes from includeTypes' {
            $defaults = @{
                includeTypes = @('a','b','c')
                excludeTypes = @('b')
                conflictMode = 'removeWins'
            }

            $result = Merge-Config -Defaults $defaults
            $result.includeTypes | Should -Be @('a','c')
        }
    }

    Context 'includeWins behavior' {
        It 'includeTypes removes from excludeTypes' {
            $defaults = @{
                includeTypes = @('a','b')
                excludeTypes = @('b','c')
                conflictMode = 'includeWins'
            }

            $result = Merge-Config -Defaults $defaults
            $result.excludeTypes | Should -Be @('c')
        }
    }

    Context 'unionWins behavior' {
        It 'keeps both arrays unchanged' {
            $defaults = @{
                includeTypes = @('a','b')
                excludeTypes = @('b','c')
                conflictMode = 'unionWins'
            }

            $result = Merge-Config -Defaults $defaults
            $result.includeTypes | Should -Be @('a','b')
            $result.excludeTypes | Should -Be @('b','c')
        }
    }

    Context 'cliWins behavior' {
        It 'replaces defaults with cli values' {
            $defaults = @{ includeTypes = @('a','b'); conflictMode = 'unionWins' }
            $cli      = @{ includeTypes = @('x','y'); conflictMode = 'cliWins' }

            $result = Merge-Config -Defaults $defaults -Cli $cli
            $result.includeTypes | Should -Be @('x','y')
            $result.conflictMode | Should -Be 'cliWins'
        }
    }

    Context 'colourKeyPath passthrough' {
        It 'preserves colourKeyPath from higher precedence' {
            $defaults = @{ colourKeyPath = 'config/COLOURS.json' }
            $cli      = @{ colourKeyPath = 'override/COLOURS.json' }

            $result = Merge-Config -Defaults $defaults -Cli $cli
            $result.colourKeyPath | Should -Be 'override/COLOURS.json'
        }

        It 'keeps defaults when overlay is null' {
            $defaults = @{ colourKeyPath = 'config/COLOURS.json' }
            $mode     = @{ colourKeyPath = $null }

            $result = Merge-Config -Defaults $defaults -Mode $mode
            $result.colourKeyPath | Should -Be 'config/COLOURS.json'
        }
    }
}

Describe 'ConflictMode registry and validation' {
    It 'loads conflict mode manifest' {
        $manifest = Get-ConflictModeManifest
        $manifest | Should -Not -BeNullOrEmpty
        $manifest.RegistryPath | Should -Not -BeNullOrEmpty
        $manifest.Validation.RequiredFields | Should -Contain 'name'
        $manifest.Validation.AllowedModes | Should -Contain 'unionWins'
        $manifest.Visualization.AsciiIndicators.Keys | Should -Contain 'cliWins'
    }

    It 'loads conflict mode registry' {
        $manifest = Get-ConflictModeManifest
        $registry = Get-ConflictModeRegistry -Manifest $manifest -Reload
        $registry.Modes | Should -Not -BeNullOrEmpty
        $registry.ModeIndex.ContainsKey('unionWins') | Should -BeTrue
        $registry.ModeIndex['unionWins'].asciiIndicator | Should -Be '='
    }

    It 'validates a known mode' {
        $manifest = Get-ConflictModeManifest
        $registry = Get-ConflictModeRegistry -Manifest $manifest
        $entry = Validate-ConflictMode -Mode 'unionWins' -Registry $registry -Manifest $manifest
        $entry.name | Should -Be 'unionWins'
    }

    It 'throws deterministic validation error for unknown mode' {
        $manifest = Get-ConflictModeManifest
        $registry = Get-ConflictModeRegistry -Manifest $manifest

        { Validate-ConflictMode -Mode 'notAMode' -Registry $registry -Manifest $manifest } |
            Should -Throw -ExpectedMessage '*ConflictModeValidationError*mode*missingFields*registryPath*manifestPath*'
    }
}

Describe 'Apply-ConflictMode' {
    It 'unions arrays for unionWins' {
        $result = Apply-ConflictMode -Mode 'unionWins' -Value @('a','b') -Incoming @('b','c')
        $result | Should -Be @('a','b','c')
    }

    It 'replaces arrays for includeWins' {
        $result = Apply-ConflictMode -Mode 'includeWins' -Value @('a','b') -Incoming @('z')
        $result | Should -Be @('z')
    }

    It 'replaces arrays for cliWins' {
        $result = Apply-ConflictMode -Mode 'cliWins' -Value @('a','b') -Incoming @('x','y')
        $result | Should -Be @('x','y')
    }
}

Describe 'ConflictMode audit trail' {
    It 'writes and replays audit entries for a parameter' {
        $manifest = Get-ConflictModeManifest
        $registry = Get-ConflictModeRegistry -Manifest $manifest
        $modeEntry = $registry.ModeIndex['unionWins']

        $layerValues = @{
            Defaults = @('a')
            Config   = @('b')
            Mode     = @('c')
            Style    = @('d')
            Cli      = @('e')
        }

        Write-ConflictModeAuditEntry -Parameter 'testParameter' -ConflictMode 'unionWins' -RegistryEntry $modeEntry -Manifest $manifest -LayerValues $layerValues -FinalMergedValue @('a','b') -WinningLayer 'Cli' | Out-Null

        $trail = Get-ConflictModeAuditTrail -Parameter 'testParameter'
        ($trail | Select-Object -Last 1).parameter | Should -Be 'testParameter'
    }
}

Describe 'Set-ConflictMode runtime update' {
    It 're-runs merge and returns updated rows' {
        $defaults = @{ includeTypes = @('a'); conflictMode = 'unionWins' }
        $cli = @{ includeTypes = @('x'); conflictMode = 'unionWins' }
        Merge-Config -Defaults $defaults -Cli $cli | Out-Null

        $rows = Set-ConflictMode -Mode 'cliWins'
        $rows | Should -Not -BeNullOrEmpty
        ($rows | Select-Object -First 1).PSObject.Properties.Name | Should -Contain 'AsciiIndicator'
    }
}

Describe 'Show-ConfigMergeTable' {
    It 'returns objects with final merged values and winner markers' {
        $defaults = @{ includeTypes = @('a'); excludeFolders = @('node_modules') }
        $mode     = @{ includeTypes = @('b') }
        $config   = @{ includeTypes = @('a','b'); conflictMode = 'unionWins' }

        $rows = Show-ConfigMergeTable -Defaults $defaults -Mode $mode -Config $config -AsObjects

        $row = $rows | Where-Object { $_.Param -eq 'includeTypes' }
        $row | Should -Not -BeNullOrEmpty
        # FinalObject should be an array containing 'a' and 'b'
        $row.FinalObject | Should -Be @('a','b')
        # WinnerLayers should reflect highest-precedence contributor in this fixture
        ($row.WinnerLayers -split ', ' ) | Should -Contain 'Mode'
        $row.PSObject.Properties.Name | Should -Contain 'ConflictModeName'
        $row.PSObject.Properties.Name | Should -Contain 'AsciiIndicator'
        $row.PSObject.Properties.Name | Should -Contain 'WinningLayer'
        $row.PSObject.Properties.Name | Should -Contain 'OverrideMarker'
        $row.PSObject.Properties.Name | Should -Contain 'UDICompliant'
    }
}
